const cap=2097152,ending='\n/*JD_REF:'+symbol('a')+'*/',t=apis.candidate.phase61Cap;
// Remaining-fuel boundaries exercise the exact old state transition without a quadratic 2MiB old scan.
const small=[];
for(const fuel of [32,257])for(const [name,n,marker,expected]of [
  ['raw-below',fuel-1,'',[]],['raw-exact',fuel,'',[]],['raw-above',fuel+1,'',null],
  ['marker-ending-exact',fuel,ending,['a']],['marker-crossing',fuel+1,ending,null]])
  small.push({name:name+'-'+fuel,text:'x'.repeat(n-marker.length)+marker,fuel,expected});
small.push({name:'empty-zero',text:'',fuel:0,expected:[]},{name:'nonempty-zero',text:'x',fuel:0,expected:null});
for(const c of small) {
  mark('small-scanner-differential',{name:c.name,fuel:c.fuel});
  const observed={};for(const role of ['baseline','candidate']) {
    observed[role]=decode(apis[role].phase61CapOld(tables[role],c.text,c.fuel));
    assert.deepEqual(observed[role],c.expected,c.name+': '+role);
  }
  report.smallScannerDifferential.push({...c,observed,pass:true});save();
}
